    /**
     * Handles create a Alert.  if not key provided, calls create, otherwise calls save
     * @param		Alert	alert
     * @return		Alert 
     */
	@PostMapping("/create")
    public Alert create( @RequestBody(required=true) CreateAlertCommand command ) {
    	Alert entity = null;
		try {       
        	
			entity = AlertBusinessDelegate.getAlertInstance().createAlert( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return entity;
    }

    /**
     * Handles updating a Alert.  if no key provided, calls create, otherwise calls save
     * @param		Alert alert
     * @return		Alert
     */
	@PutMapping("/update")
    public Alert update( @RequestBody(required=true) UpdateAlertCommand command ) {
		Alert entity = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateAlertCommand
			// -----------------------------------------------
			entity = AlertBusinessDelegate.getAlertInstance().updateAlert(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "AlertController:update() - successfully update Alert - " + exc.getMessage());        	
	    }		
		
		return entity;
	}
 
    /**
     * Handles deleting a Alert entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteAlertCommand command ) {                
    	try {
        	AlertBusinessDelegate delegate = AlertBusinessDelegate.getAlertInstance();

        	delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Alert with key " + command.getAlertId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }

	}        
	
    /**
     * Handles loading a Alert using a UUID
     * @param		UUID uuid 
     * @return		Alert
     */    
    @GetMapping("/load")
    public Alert load( @RequestParam(required=true) UUID uuid ) {    	
    	Alert entity = null;

    	try {  
    		entity = AlertBusinessDelegate.getAlertInstance().getAlert( new AlertFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Alert using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Alert business objects
     * @return		Set<Alert>
     */
    @GetMapping("/")
    public List<Alert> loadAll() {                
    	List<Alert> alertList = null;
        
    	try {
            // load the Alert
            alertList = AlertBusinessDelegate.getAlertInstance().getAllAlert();
            
            if ( alertList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Alerts" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Alerts ", exc );
        	return null;
        }

        return alertList;
                            
    }

